const pin = root.querySelector(".pin");
gsap.set(ptr, { drawSVG: "0%" });
gsap.set(pin, { scale: 0, transformOrigin: "50% 50%" });
for (let i = 0; i < bars.length; i++) {
  mt.fromTo(bars[i], { attr: { y: 920, height: 0 } }, { attr: { y: 920 - h[i], height: h[i] }, duration: 1.1, ease: "expo.out", immediateRender: false }, 0.25 + i * 0.11);
}
const a = anchors[beats[0].id].title;
const lift = Math.min(40, Math.max(0, -a.y - a.h));
mt.to(pin, { scale: 1, duration: 0.5, ease: "back.out(2)" }, 1.05);
mt.to(ptr, { drawSVG: "100%", y: -lift, duration: 0.9, ease: "expo.inOut" }, 1.15);
mt.to(bars, { y: -8, duration: Math.max(0.6, D - 2.2), ease: "sine.inOut", stagger: 0.08 }, 1.9);

